class Solution {
public:
    long long S(long long R, int n) {
        if (R <= 0) return 0;
        long long res = 0, prefix = 0;
        for (int i = 60; i >= 0; --i) {
            if ((R >> i) & 1LL) {
                int m = 0; long long freeSum = 0;
                for (int q = 0; q < i; ++q)
                    if (!((n >> q) & 1)) { m++; freeSum += q; }
                res += prefix * (1LL << m);
                res += freeSum * (1LL << (m > 0 ? m - 1 : 0));
                prefix |= 1LL << i;
            }
        }
        if ((R & n) == 0) res += R;
        return res;
    }
    long long sumCompatible(int n, int k) {
        return S(n + k, n) - S((long long)n - k - 1, n);
    }
};

