    private long S(long R, int n) {
        if (R <= 0) return 0;
        long res = 0, prefix = 0;
        for (int i = 60; i >= 0; i--) {
            if (((R >> i) & 1L) != 0) {
                int m = 0; long freeSum = 0;
                for (int q = 0; q < i; q++)
                    if (((n >> q) & 1) == 0) { m++; freeSum += q; }
                res += prefix * (1L << m);
                res += freeSum * (m > 0 ? (1L << (m - 1)) : 0);
                prefix |= 1L << i;
            }
        }
        if ((R & n) == 0) res += R;
        return res;
    }
    public long sumCompatible(int n, int k) {
        return S(n + k, n) - S((long) n - k - 1, n);
    }
}

